use vstd::prelude::*;

verus! {

fn swap_first_and_last(a: &Vec<i32>) -> (result: Vec<i32>)
    requires
        a.len() > 0,
    ensures
        result.len() == a.len(),
        // Interior elements unchanged
        forall|i: int| 1 <= i && i < a.len() as int - 1 ==> result[i] == a[i],
        // First/last swapped (also correct when len == 1)
        result[0] == a[a.len() - 1],
        result[a.len() - 1] == a[0],
{
    let n: usize = a.len();
    let mut result = a.clone();

    // After cloning, all elements match `a`.
    assert(result.len() == n);
    assert(forall|i: int| 0 <= i && i < n as int ==> result[i] == a[i]);

    if n == 1 {
        // Then the swap conditions reduce to result[0] == a[0], which holds by clone.
        return result;
    }

    let first = result[0];
    let last = result[n - 1];
    result.set(0, last);
    result.set(n - 1, first);

    // Prove interior unchanged: only indices 0 and n-1 were modified.
    assert(forall|i: int|
        1 <= i && i < n as int - 1 ==> result[i] == a[i]
    ) by {
        assert(forall|i: int|
            1 <= i && i < n as int - 1 ==> i != 0 && i != (n as int - 1)
        );
        // `set` only changes the targeted index, so interior indices remain as in the clone.
        assert(forall|i: int| 1 <= i && i < n as int - 1 ==> result[i] == a[i]);
    };

    // First/last swapped by construction
    assert(result[0] == a[n - 1]);
    assert(result[n - 1] == a[0]);

    result
}

} // verus!

